import json, os
import re

# Load grids from the session
def load():
    d = os.environ['RLM_SESSION_DIR']
    session_name = os.path.basename(d)
    t = open(d + '/../../sessions/' + session_name + '.jsonl').read()
    grids = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = []
        rest = t[m.end():].split('\n')[:h]
        for r in rest:
            rows.append([int(x) for x in r.split()])
        if k not in grids and all(len(row) == w for row in rows):
            grids[k] = rows
    return grids

G = load()
print("Keys found:", sorted(G.keys()))
for key in sorted(G.keys()):
    print(f"\n=== {key} ({len(G[key][0])}x{len(G[key])}) ===")
    for row in G[key]:
        print(' '.join(f'{x:2}' for x in row))

